-- =====================================================================
-- 05_vector.sql  |  Vector database layer (pgvector inside PostgreSQL)
--   Model     : all-MiniLM-L6-v2  (384 dimensions, normalised)
--   Storage   : vector(384) columns on students and internships
--   Metric    : cosine distance  (<=>)   similarity = 1 - distance
--   Index     : HNSW (vector_cosine_ops)
--   Embeddings are generated by scripts/embed.mjs and written with
--   UPDATE ... SET description_embedding = $1::vector
-- =====================================================================
\c talentmatch

-- 1. Verify extension and vector columns
SELECT extname, extversion FROM pg_extension WHERE extname = 'vector';
SELECT table_name, column_name, udt_name
FROM information_schema.columns
WHERE udt_name = 'vector';

-- 2. How embeddings are stored (run by embed.mjs, one row at a time)
--    UPDATE students    SET profile_embedding     = '[0.012, -0.044, ...]'::vector WHERE student_id = 1;
--    UPDATE internships SET description_embedding = '[0.031,  0.007, ...]'::vector WHERE internship_id = 1;

-- 3. Coverage check: how many rows have embeddings
SELECT 'students' AS tbl, COUNT(*) AS total, COUNT(profile_embedding) AS embedded FROM students
UNION ALL
SELECT 'internships', COUNT(*), COUNT(description_embedding) FROM internships;

-- 4. Cache the semantic match score on every application
UPDATE applications
SET match_score = fn_compute_match_score(student_id, internship_id);

-- 5. Recommend the top-N open internships for a student (excludes ones already applied to)
CREATE OR REPLACE FUNCTION fn_recommend_internships(p_student_id INT, p_limit INT DEFAULT 5)
RETURNS TABLE (internship_id INT, title VARCHAR, company VARCHAR, similarity NUMERIC) AS $$
    SELECT i.internship_id, i.title, c.name,
           ROUND((1 - (i.description_embedding <=> s.profile_embedding))::numeric, 4)
    FROM students s
    JOIN internships i ON i.status = 'Open'
                      AND (i.deadline IS NULL OR i.deadline >= CURRENT_DATE)
                      AND i.description_embedding IS NOT NULL
    JOIN companies c ON c.company_id = i.company_id
    WHERE s.student_id = p_student_id
      AND NOT EXISTS (SELECT 1 FROM applications a
                      WHERE a.student_id = s.student_id AND a.internship_id = i.internship_id)
    ORDER BY i.description_embedding <=> s.profile_embedding
    LIMIT p_limit;
$$ LANGUAGE sql STABLE;

-- 6. Rank the applicants of an internship by semantic fit (recruiter view)
CREATE OR REPLACE FUNCTION fn_rank_applicants(p_internship_id INT)
RETURNS TABLE (rank BIGINT, application_id INT, student_name VARCHAR, status VARCHAR, similarity NUMERIC) AS $$
    SELECT RANK() OVER (ORDER BY s.profile_embedding <=> i.description_embedding),
           a.application_id, s.name, a.status,
           ROUND((1 - (s.profile_embedding <=> i.description_embedding))::numeric, 4)
    FROM applications a
    JOIN students s    ON s.student_id    = a.student_id
    JOIN internships i ON i.internship_id = a.internship_id
    WHERE a.internship_id = p_internship_id
      AND s.profile_embedding IS NOT NULL AND i.description_embedding IS NOT NULL
    ORDER BY 1;
$$ LANGUAGE sql STABLE;

-- 7. Demo: recommendations for student 1 and applicant ranking for internship 3
SELECT * FROM fn_recommend_internships(1, 5);
SELECT * FROM fn_rank_applicants(4);

-- 8. Semantic search from free text.
--    The Next.js API embeds the user's query text first, then runs:
--      SELECT internship_id, title,
--             1 - (description_embedding <=> $1::vector) AS similarity
--      FROM internships
--      WHERE status = 'Open'
--      ORDER BY description_embedding <=> $1::vector
--      LIMIT 10;
--    Equivalent demo using an existing student profile as the "query":
SELECT i.internship_id, i.title,
       ROUND((1 - (i.description_embedding <=> s.profile_embedding))::numeric, 4) AS similarity
FROM internships i, students s
WHERE s.student_id = 2 AND i.status = 'Open'
ORDER BY i.description_embedding <=> s.profile_embedding
LIMIT 5;

-- 9. Hybrid search: 60% semantic similarity + 40% keyword rank (full-text)
SELECT i.internship_id, i.title,
       ROUND((0.6 * (1 - (i.description_embedding <=> s.profile_embedding))
            + 0.4 * ts_rank(to_tsvector('english', i.title || ' ' || i.description),
                            plainto_tsquery('english', 'python data')))::numeric, 4) AS hybrid_score
FROM internships i, students s
WHERE s.student_id = 5 AND i.status = 'Open'
ORDER BY hybrid_score DESC
LIMIT 5;

-- 10. Index usage and tuning
SET hnsw.ef_search = 40;     -- accuracy / speed trade-off for HNSW queries
SET enable_seqscan = off;    -- force the planner to use the index on this tiny demo table
EXPLAIN ANALYZE
SELECT internship_id FROM internships
ORDER BY description_embedding <=> (SELECT profile_embedding FROM students WHERE student_id = 1)
LIMIT 5;
RESET enable_seqscan;
